window.kbPageData["views/entry/k-ce4897cd351e7073"] = {"key":"entry/k-ce4897cd351e7073","state":{"route":"entry/k-ce4897cd351e7073"},"node":{"id":"k-ce4897cd351e7073","mode":"k","title":"新型举国体制","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#19","政治理论必刷100题#26"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["innovation"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论","科技"],"来源主题":["产业、科技与对外开放"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"新型举国体制是在国家统筹下，发挥市场机制作用，组织各方力量完成国家重大任务的制度安排。科技领域的重要应用是组织关键核心技术攻关。","review":{"title":"新型举国体制","type":"制度与规则","definition":"新型举国体制是在国家统筹下，发挥市场机制作用，组织各方力量完成国家重大任务的制度安排。科技领域的重要应用是组织关键核心技术攻关。","explanation":"科技攻关涉及企业、高校、科研机构等主体。2024年《中共中央关于进一步全面深化改革、推进中国式现代化的决定》在深化科技体制改革部署中提出，优化重大科技创新组织机制，统筹强化关键核心技术攻关，强化企业科技创新主体地位。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"深化科技体制改革"}],"examFocus":{"政治理论必刷100题#19":"对照科技强国建设部署，核对科技的战略作用、举国体制、国际科技合作与青年人才培养的表述。","政治理论必刷100题#26":"把技术攻关放在做强国内大循环的部署中，同企业帮扶、就业和供需调整等要求一并核对。"}},"aspects":[{"title":"科技强国建设与科技自立自强","uses":[{"unit":"Q1","role":"直接考查","use":"题目要求选出建成科技强国相关表述中的错误项。2025年《求是》刊载的《朝着建成科技强国的宏伟目标奋勇前进》提出发挥新型举国体制优势，C项写成发挥传统举国体制优势，因此选C。","evidence":"充分发挥新型举国体制优势","qids":["政治理论必刷100题#19"]}]},{"title":"关键核心技术与前沿技术攻关","uses":[{"unit":"Q2","role":"直接考查","use":"在做强国内大循环的语境中，D项把健全新型举国体制与强化技术攻关、完善战略性产业发展政策和治理体系相联系，符合题据所引的2025年文章，因而排除D项。题目要求选错，答案为A。","evidence":"健全新型举国体制，强化关键核心技术和前沿技术攻关","qids":["政治理论必刷100题#26"]}]}],"sources":[{"id":"af1bf95a1262a21a","label":"新型举国体制","topic":"产业、科技与对外开放","category":"非时政","text":"2.新型举国体制\n新型举国体制是以国家发展和国家安全为目标，通过统筹资源配置与跨领域协同攻关，\n集中力量突破关键核心技术的国家战略组织模式。","source":{"doc":"6cbfb01fe723bba64b75","first":27,"last":27,"page":27,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#19":{"paper":"政治理论必刷100题","n":19,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",6],"asrc":["国省考政治理论必刷100题.pdf",42],"card":"980996764404edeabd39ba8b","links":[{"id":"k-ce4897cd351e7073","role":"直接考查","why":"建成科技强国的部署要求发挥新型举国体制优势，加快推进高水平科技自立自强。"}]},"政治理论必刷100题#26":{"paper":"政治理论必刷100题","n":26,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",8],"asrc":["国省考政治理论必刷100题.pdf",47],"card":"46fbb8f5881a8468bfaa2772","links":[{"id":"k-ce4897cd351e7073","role":"直接考查","why":"健全新型举国体制是组织关键核心技术和前沿技术攻关、推动战略性产业发展的政策要求。"}]}},"terms":{},"references":{"reform":{"name":"《中共中央关于进一步全面深化改革、推进中国式现代化的决定》（2024年）","url":"https://www.miit.gov.cn/xwdt/szyw/art/2024/art_7ba61714bf074c29b0135ddfe4c1e7cd.html"}},"topics":[{"slug":"innovation","title":"科技创新与科研组织"}],"units":{"k-ce4897cd351e7073":[["政治理论必刷100题#19"],["政治理论必刷100题#26"]]}};
